// Switched off? Then do nothing at all: no request to the page, no message. The watch turns itself off when it
// reaches its final state or after too many days without a change (see the next Code node), so nobody has to
// remember to unpublish it.
if ($getWorkflowStaticData('global').done) return [];
return $input.all();

// ---- Adapt these (or ask the assistant to) ----
const LABEL = '__LABEL__';                    // what this is, shown in the message: "Parcel 1234", "Price of X"
const URL_SHOWN = '__URL__';                  // shown in the message
const FINAL = /(?!)/;                        // the end state, e.g. /delivered|entregado/i (this default never matches)
const MAX_DAYS_UNCHANGED = 14;               // switch off after this many days with no change (0 = never)
// What to compare. Default: the visible text of the page, between two markers if you give them. For a parcel
// tracker, return the latest row only (date + place + status) so a change elsewhere on the page does not count.
const START = '';  // e.g. 'trace Details'
const END = '';
function extract(html) {
  let t = String(html || '').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, '\n').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
  if (START && t.includes(START)) t = t.slice(t.indexOf(START) + START.length);
  if (END && t.includes(END)) t = t.slice(0, t.indexOf(END));
  return t.split('\n').map(l => l.trim()).filter(Boolean).join('\n').slice(0, 600);
}
// -----------------------------------------------
const now = Date.now();
const mem = $getWorkflowStaticData('global');
const current = extract($input.first().json.data);
if (!current) throw new Error('Nothing to compare: the page changed shape or the markers are wrong');
const footer = '\n\n— automatic notice from n8n';
if (mem.last === undefined) { mem.last = current; mem.changedAt = now; return []; }   // first run: remember only
if (current !== mem.last) {
  mem.last = current; mem.changedAt = now;
  let text = '🔔 ' + LABEL + ': it changed\n' + current.slice(0, 400) + '\n' + URL_SHOWN;
  if (FINAL.test(current)) { mem.done = true; text += '\n\n✅ That is the final state: this watch has switched itself off.'; }
  return [{ json: { text: text + footer } }];
}
if (MAX_DAYS_UNCHANGED > 0 && now - (mem.changedAt || now) > MAX_DAYS_UNCHANGED * 86400000) {
  mem.done = true;
  return [{ json: { text: '💤 ' + LABEL + ': no change in ' + MAX_DAYS_UNCHANGED + ' days, so this watch has switched itself off.\nLast state:\n' + current.slice(0, 300) + footer } }];
}
return [];
